#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import os, re, sys, json, time, hashlib, glob, uuid, math
from datetime import datetime
from pathlib import Path

# Opcionális, de ajánlott csomagok
try:
    import trafilatura
except Exception:
    trafilatura = None
try:
    import fitz  # PyMuPDF
except Exception:
    fitz = None
try:
    from pdfminer.high_level import extract_text as pdfminer_extract_text
except Exception:
    pdfminer_extract_text = None
try:
    from langdetect import detect as lang_detect
except Exception:
    lang_detect = None
try:
    from simhash import Simhash
except Exception:
    Simhash = None
try:
    import ftfy
except Exception:
    ftfy = None

# ------------------------------
# Konfiguráció
# ------------------------------
IN_DIR = "exa_downloads"  # Exa AI által letöltött fájlok (HTML/PDF) gyökere
OUT_DIR = "out"
RAW_TXT_DIR = os.path.join(OUT_DIR, "txt_raw")
CLEAN_TXT_DIR = os.path.join(OUT_DIR, "txt_clean")
JSONL_FILE = os.path.join(OUT_DIR, "corpus.jsonl")
DEDUP_DB = os.path.join(OUT_DIR, "dedup.json")
LOG_FILE = os.path.join(OUT_DIR, "process_log.jsonl")

CHUNK_SIZE = 1200
CHUNK_OVERLAP = 0.12  # 12%
