os.makedirs(CLEAN_TXT_DIR, exist_ok=True)
os.makedirs(OUT_DIR, exist_ok=True)

# ------------------------------
# Segédfüggvények
# ------------------------------

def now_iso():
    return datetime.utcnow().isoformat() + "Z"

def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def sha256_str(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8", errors="ignore")).hexdigest()

def simhash_text(s: str) -> str:
    if not Simhash:
        return ""
    return hex(Simhash(s).value)

def read_bytes(path: str) -> bytes:
    with open(path, "rb") as f:
        return f.read()

def write_text(path: str, text: str):
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)

def append_jsonl(path: str, obj: dict):
    with open(path, "a", encoding="utf-8") as f:
        f.write(json.dumps(obj, ensure_ascii=False) + "\n")

def load_json(path: str, default):
    if not os.path.exists(path):
        return default
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def save_json(path: str, obj: dict):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)

def guess_ext(path: str) -> str:
    ext = Path(path).suffix.lower().lstrip(".")
    if ext in {"htm"}:
        return "html"
    return ext

# ------------------------------
# PDF/HTML kinyerés
# ------------------------------

def extract_text_html(html_bytes: bytes) -> str:
    # Trafialtura a legjobb, fallback: egyszerűbb tisztítás
    txt = ""
    if trafilatura:
        try:
            txt = trafilatura.extract(html_bytes.decode("utf-8", errors="ignore"),
                                      include_comments=False,
                                      include_formatting=False,
                                      include_tables=False,
                                      favor_recall=True)
            if txt:
                return txt
        except Exception:
            pass
    # Fallback: nagyon nyers
    s = html_bytes.decode("utf-8", errors="ignore")
    s = re.sub(r"(?is)<script.*?>.*?</script>", " ", s)
    s = re.sub(r"(?is)<style.*?>.*?</style>", " ", s)
    s = re.sub(r"(?is)<[^>]+>", " ", s)
    s = re.sub(r"\s+", " ", s)
    return s.strip()

def extract_text_pdf(pdf_path: str) -> str:
    # 1) PyMuPDF
    if fitz:
        try:
            doc = fitz.open(pdf_path)
            pages = []
            for i in range(len(doc)):
                pages.append(doc[i].get_text("text"))
            t = "\n".join(pages).strip()
            if t:
                return t
        except Exception:
            pass
    # 2) pdfminer
    if pdfminer_extract_text:
        try:
            t = pdfminer_extract_text(pdf_path)
            if t:
                return t.strip()
        except Exception:
            pass
    # 3) Fallback: nincs szöveg
    return ""

# ------------------------------
# Normalizálás és jogszabály-specifikus felismerések
# ------------------------------

def normalize_text(s: str) -> str:
    if ftfy:
        s = ftfy.fix_text(s)
    # nem törhető szóközök -> rendes
    s = s.replace("\u00A0", " ")
    # kötőjeles sortörések javítása: pl. "rendel-\nkezik" -> "rendelkezik"
    s = re.sub(r"(\w)-\n(\w)", r"\1\2", s)
    # többszörös whitespace
    s = re.sub(r"[ \t\r\f\v]+", " ", s)
    s = re.sub(r"\n{3,}", "\n\n", s)
    s = re.sub(r" +\n", "\n", s)
    s = re.sub(r"\n +", "\n", s)
    return s.strip()

LAW_ID_REGEX = re.compile(
    r"(?P<year>19\d{2}|20\d{2})\.\s*évi\s*(?P<num>[IVXLCDM]+|\d+)\.\s*(?P<type>törvény|tv\.)",
    re.IGNORECASE
)
SECTION_REGEX = re.compile(r"^\s*\d+\.?\s*§", re.MULTILINE)
HATALY_REGEX = re.compile(r"hatály(?:ba lép|on kívül helyez).*?(?P<date>\d{4}\.\d{2}\.\d{2})", re.IGNORECASE)

def infer_law_meta(text: str) -> dict:
    meta = {}
    m = LAW_ID_REGEX.search(text)
    if m:
        meta["law_year"] = m.group("year")
        meta["law_number"] = m.group("num")
        meta["law_type"] = m.group("type").lower()
    # § szakaszok sűrűsége
    sections = len(SECTION_REGEX.findall(text))
    meta["section_count"] = sections
    # hatály kulcsszavak és dátumok
    m2 = HATALY_REGEX.search(text)
    if m2:
        meta["hatály_dátum"] = m2.group("date")
    return meta

def detect_lang(text: str) -> str:
    if not lang_detect:
        return "hu"  # ha nincs lib, ne zárjunk ki
    try:
        return lang_detect(text)
    except Exception:
        return "und"

# ------------------------------
# Deduplikáció
# ------------------------------

def load_dedup():
    db = load_json(DEDUP_DB, {"sha256": {}, "simhash": {}})
    return db

def save_dedup(db):
    save_json(DEDUP_DB, db)

def is_duplicate(text: str, db: dict, simhash_threshold=5) -> bool:
    h = sha256_str(text)
    if h in db["sha256"]:
        return True
    if Simhash:
        s = Simhash(text)
        for key, val in db["simhash"].items():
            try:
                other = int(key, 16)
                dist = Simhash(other).distance(s)
            except Exception:
                continue
            if dist <= simhash_threshold:
                return True
    return False

def register_doc(text: str, db: dict):
    h = sha256_str(text)
    db["sha256"][h] = True
    if Simhash:
        db["simhash"][simhash_text(text)] = True

# ------------------------------
# Chunkolás
# ------------------------------

